namespace airmuse { LyricsService::LyricsService(Loader l):loader_(std::move(l)){} LyricsService::~LyricsService(){if(task_.joinable())task_.request_stop();} void LyricsService::Request(const MediaSnapshot&s,std::function<void(const Lyrics&)> done){auto key=s.identity.stableId.empty()?s.title+"|"+s.artist:s.identity.stableId;std::optional<Lyrics> cached;std::uint64_t g;{std::lock_guard l(mutex_);if(auto it=cache_.find(key);it!=cache_.end())cached=it->second;else {++generation_;g=generation_;if(task_.joinable())task_.request_stop();}}if(cached){done(*cached);return;} task_=std::jthread([this,s,key,g,done=std::move(done)](std::stop_token stop){auto r=loader_(s,stop);if(stop.stop_requested())return;bool current;{std::lock_guard l(mutex_);current=g==generation_;if(current)cache_[key]=r;}if(current)done(r);});} }
